import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import { isLive } from "@/lib/soft-delete";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { Issue, IssueRollup, IssueStatus } from "@/types/issue";

/**
 * Sub-issue tree rules.
 *
 * An issue may sit under a parent issue of its own project. Trees stay
 * shallow — a root issue is level 0 and nothing sits deeper than
 * `MAX_SUB_ISSUE_DEPTH` — and never loop. The service layer loads the rows;
 * the decisions live here so they exist once.
 */

export type IssueHierarchyViolation = "cycle" | "too_deep";

/** A placement would loop the tree or push part of it too deep. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: IssueHierarchyViolation,
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its sub-issues.`
        : `Issue ${issueId} would sit deeper than level ${MAX_SUB_ISSUE_DEPTH}.`,
    );
    this.name = "IssueHierarchyError";
  }
}

export function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** Live and not done or canceled. */
export function isOpenIssue(issue: Issue): boolean {
  return isLive(issue) && !isClosedStatus(issue.status);
}

/**
 * Guards hanging an issue — and everything below it — under a parent.
 *
 * `lineage` is the parent followed by its ancestors up to the root, so the
 * placed issue lands at level `lineage.length`; `height` is how many levels
 * sit below the placed issue (0 for a leaf). `issueId` is `null` for an issue
 * that does not exist yet, which cannot close a loop.
 */
export function assertPlacement(
  issueId: string | null,
  lineage: readonly string[],
  height: number,
): void {
  if (issueId !== null && lineage.includes(issueId)) {
    throw new IssueHierarchyError(issueId, "cycle");
  }
  if (lineage.length + height > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId ?? lineage[0] ?? "", "too_deep");
  }
}

/** Counts the live issues among `below`; archived rows are ignored. */
export function rollupOf(below: readonly Issue[]): IssueRollup {
  let total = 0;
  let closed = 0;
  for (const issue of below) {
    if (!isLive(issue)) continue;
    total += 1;
    if (isClosedStatus(issue.status)) closed += 1;
  }
  return { total, open: total - closed, closed };
}

