/**
 * Sub-issues: placement guards, listing, roll-up, cascading archive and the
 * completion notice to the parent's assignee.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { toAppError } from "@/lib/errors";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("subissues");
  other = await createTenant("subissues-other");
});

afterAll(() => {
  cleanup();
});

async function create(
  title: string,
  parentId: IssueId | null = null,
  assigneeId: UserId | null = null,
): Promise<Issue> {
  return issueService.createIssue(tenant.actors.member, {
    ...issueInput(tenant.org.id, tenant.project.id, { title, assigneeId }),
    parentId,
  });
}

async function place(issue: Issue, parentId: IssueId | null): Promise<Issue> {
  return issueService.setIssueParent(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    parentId,
  });
}

async function close(issue: Issue, status: "done" | "canceled" = "done"): Promise<void> {
  await issueService.changeIssueStatus(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    status,
  });
}

async function completionNotices(recipientId: UserId): Promise<number> {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["sub_issues_completed"],
    limit: 100,
    cursor: null,
  });
  return page.total;
}

describe("placing issues", () => {
  it("creates an issue under a parent and moves it back to the root", async () => {
    const parent = await create("Parent at creation");
    const child = await create("Child at creation", parent.id);
    expect(child.parentId).toBe(parent.id);

    const seen: unknown[] = [];
    const off = subscribe("issue.updated", (payload) => {
      seen.push(payload);
    });
    try {
      const root = await place(child, null);
      expect(root.parentId).toBeNull();
      expect(await issueRepo.findIssueById(tenant.org.id, child.id)).toEqual(root);
      expect(seen).toEqual([
        expect.objectContaining({ issueId: child.id, changedFields: ["parentId"] }),
      ]);
    } finally {
      off();
    }
  });

  it("refuses loops", async () => {
    const top = await create("Loop top");
    const middle = await create("Loop middle", top.id);
    const bottom = await create("Loop bottom", middle.id);

    await expect(place(top, top.id)).rejects.toMatchObject({ reason: "cycle" });
    await expect(place(top, bottom.id)).rejects.toBeInstanceOf(IssueHierarchyError);
    expect((await issueRepo.findIssueById(tenant.org.id, top.id))?.parentId).toBeNull();
  });

  it("judges depth by the deepest descendant", async () => {
    const level0 = await create("Depth 0");
    const level1 = await create("Depth 1", level0.id);
    const level2 = await create("Depth 2", level1.id);
    const level3 = await create("Depth 3", level2.id);

    await expect(create("Depth 4", level3.id)).rejects.toMatchObject({
      reason: "too_deep",
    });

    const otherRoot = await create("Other root");
    const otherChild = await create("Other child", otherRoot.id);
    // otherRoot has one level below it: under level2 its child would land at 4.
    await expect(place(otherRoot, level2.id)).rejects.toMatchObject({
      reason: "too_deep",
    });
    await expect(place(otherRoot, level1.id)).resolves.toMatchObject({
      parentId: level1.id,
    });
    expect((await issueRepo.findIssueById(tenant.org.id, otherChild.id))?.parentId).toBe(
      otherRoot.id,
    );
  });

  it("requires a live parent of the same project and workspace", async () => {
    const issue = await create("Needs a parent");

    const project = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Second project",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: tenant.userIds.owner,
      color: "#6366f1",
      targetDate: null,
    });
    const elsewhere = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project.id, { title: "Other project" }),
    );
    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Other workspace" }),
    );
    const archived = await create("Archived parent");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    await expect(place(issue, elsewhere.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(place(issue, foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(place(issue, archived.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(create("Child of archived", archived.id)).rejects.toBeInstanceOf(
      AlreadyArchivedError,
    );
  });

  it("guards scope, existence, permission and archived issues", async () => {
    const parent = await create("Guarded parent");
    const issue = await create("Guarded issue");

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: other.org.id,
        issueId: issue.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.setIssueParent(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      issueService.listSubIssues(tenant.actors.member, tenant.org.id, "nope" as IssueId),
    ).rejects.toBeInstanceOf(NotFoundError);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    await expect(place(issue, parent.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("maps IssueHierarchyError to a conflict", () => {
    const shape = toAppError(new IssueHierarchyError("01ISS", "too_deep"));
    expect(shape.code).toBe("conflict");
    expect(shape.meta?.reason).toBe("too_deep");
  });
});

describe("reading the tree", () => {
  it("lists live direct sub-issues oldest first and rolls up every level", async () => {
    const parent = await create("Roll-up parent");
    const a = await create("Roll-up A", parent.id);
    const b = await create("Roll-up B", parent.id);
    const c = await create("Roll-up C", parent.id);
    const grandchild = await create("Roll-up grandchild", a.id);
    await close(b);
    await close(grandchild, "canceled");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, c.id);

    const listed = await issueService.listSubIssues(
      tenant.actors.viewer,
      tenant.org.id,
      parent.id,
    );
    expect(listed.map((issue) => issue.id)).toEqual([a.id, b.id]);

    expect(
      await issueService.getIssueRollup(tenant.actors.viewer, tenant.org.id, parent.id),
    ).toEqual({ total: 3, open: 1, closed: 2 });
  });
});

describe("archiving", () => {
  it("archives every live issue below, announcing each once", async () => {
    const parent = await create("Archive parent");
    const top = await create("Archive top", parent.id);
    const child = await create("Archive child", top.id);
    const grandchild = await create("Archive grandchild", child.id);
    const earlier = await issueRepo.archiveIssue(tenant.org.id, grandchild.id);

    const seen: IssueId[] = [];
    const off = subscribe("issue.archived", (payload) => {
      seen.push(payload.issueId);
    });
    try {
      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, top.id);
    } finally {
      off();
    }

    expect(seen).toEqual([top.id, child.id]);
    expect((await issueRepo.findIssueById(tenant.org.id, child.id))?.archivedAt).not.toBeNull();
    expect((await issueRepo.findIssueById(tenant.org.id, grandchild.id))?.archivedAt).toBe(
      earlier.archivedAt,
    );
    expect((await issueRepo.findIssueById(tenant.org.id, parent.id))?.archivedAt).toBeNull();
  });
});

describe("completion notice", () => {
  it("tells the parent's assignee once, when the last open sub-issue closes", async () => {
    const assignee = tenant.userIds.admin;
    const before = await completionNotices(assignee);

    const parent = await create("Notice parent", null, assignee);
    const a = await create("Notice A", parent.id);
    const b = await create("Notice B", parent.id);

    await close(a);
    expect(await completionNotices(assignee)).toBe(before);

    await close(b);
    expect(await completionNotices(assignee)).toBe(before + 1);

    await close(b, "canceled");
    expect(await completionNotices(assignee)).toBe(before + 1);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: b.id,
      status: "todo",
    });
    await close(b);
    expect(await completionNotices(assignee)).toBe(before + 2);
  });

  it("counts archiving an open sub-issue as closing it", async () => {
    const assignee = tenant.userIds.admin;
    const before = await completionNotices(assignee);

    const parent = await create("Archive notice parent", null, assignee);
    const child = await create("Archive notice child", parent.id);
    await create("Archive notice grandchild", child.id);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);
    expect(await completionNotices(assignee)).toBe(before + 1);
  });

  it("stays quiet for open descendants, moves and one's own changes", async () => {
    const assignee = tenant.userIds.admin;
    const before = await completionNotices(assignee);

    const parent = await create("Quiet parent", null, assignee);
    const child = await create("Quiet child", parent.id);
    await create("Quiet grandchild", child.id);
    await close(child);

    const moved = await create("Quiet moved", parent.id);
    await place(moved, null);

    expect(await completionNotices(assignee)).toBe(before);

    const own = await create("Own parent", null, tenant.userIds.member);
    const ownChild = await create("Own child", own.id);
    await close(ownChild);
    expect(await completionNotices(tenant.userIds.member)).toBe(0);
  });
});

